import{_ as p,r as n,o,c as i,e as s,a as l,s as c}from"./chunks/framework.CXcwiNg-.js";const b=JSON.parse('{"title":"Sending Mail - October CMS - 3.x","titleTemplate":false,"description":"Learn how to send mail and create templates.","frontmatter":{"subtitle":"Learn how to send mail and create templates."},"headers":[{"level":2,"title":"Message Content","slug":"message-content","link":"#message-content","children":[{"level":3,"title":"Defining Templates in the Backend Panel","slug":"defining-templates-in-the-backend-panel","link":"#defining-templates-in-the-backend-panel","children":[]},{"level":3,"title":"Defining Layouts in the Backend Panel","slug":"defining-layouts-in-the-backend-panel","link":"#defining-layouts-in-the-backend-panel","children":[]},{"level":3,"title":"Defining Views in the Filesystem","slug":"defining-views-in-the-filesystem","link":"#defining-views-in-the-filesystem","children":[{"level":4,"title":"Configuration Section","slug":"configuration-section","link":"#configuration-section","children":[]}]},{"level":3,"title":"Registering Templates, Layouts & Partials","slug":"registering-templates-layouts-partials","link":"#registering-templates-layouts-partials","children":[{"level":4,"title":"Registering a Template","slug":"registering-a-template","link":"#registering-a-template","children":[]},{"level":4,"title":"Registering a Layout","slug":"registering-a-layout","link":"#registering-a-layout","children":[]},{"level":4,"title":"Registering a Partial","slug":"registering-a-partial","link":"#registering-a-partial","children":[]},{"level":4,"title":"File-based Layouts","slug":"file-based-layouts","link":"#file-based-layouts","children":[]}]},{"level":3,"title":"Global Variables","slug":"global-variables","link":"#global-variables","children":[]}]},{"level":2,"title":"Sending Mail","slug":"sending-mail","link":"#sending-mail","children":[{"level":3,"title":"Quick Sending","slug":"quick-sending","link":"#quick-sending","children":[]},{"level":3,"title":"Building the Message","slug":"building-the-message","link":"#building-the-message","children":[{"level":4,"title":"Mailing Plain Text","slug":"mailing-plain-text","link":"#mailing-plain-text","children":[]},{"level":4,"title":"Mailing Parsed Raw Strings","slug":"mailing-parsed-raw-strings","link":"#mailing-parsed-raw-strings","children":[]},{"level":4,"title":"Mailing Raw Strings","slug":"mailing-raw-strings","link":"#mailing-raw-strings","children":[]}]},{"level":3,"title":"Sending Attachments","slug":"sending-attachments","link":"#sending-attachments","children":[]},{"level":3,"title":"Inline Attachments","slug":"inline-attachments","link":"#inline-attachments","children":[{"level":4,"title":"Embedding an Image in Mail Content","slug":"embedding-an-image-in-mail-content","link":"#embedding-an-image-in-mail-content","children":[]},{"level":4,"title":"Embedding Raw Data in Mail Content","slug":"embedding-raw-data-in-mail-content","link":"#embedding-raw-data-in-mail-content","children":[]}]}]},{"level":2,"title":"Queueing Mail","slug":"queueing-mail","link":"#queueing-mail","children":[{"level":3,"title":"Queueing a Mail Message","slug":"queueing-a-mail-message","link":"#queueing-a-mail-message","children":[]},{"level":3,"title":"Delayed Message Queueing","slug":"delayed-message-queueing","link":"#delayed-message-queueing","children":[]},{"level":3,"title":"Pushing to Specific Queues","slug":"pushing-to-specific-queues","link":"#pushing-to-specific-queues","children":[{"level":4,"title":"See Also","slug":"see-also","link":"#see-also","children":[]}]}]}],"relativePath":"3.x/extend/system/sending-mail.md","filePath":"3.x/extend/system/sending-mail.md"}'),u={name:"3.x/extend/system/sending-mail.md"};function r(d,a,g,k,m,h){const e=n("pre-heading"),t=n("post-heading");return o(),i("div",null,[s(e),a[0]||(a[0]=l("h1",null,"Sending Mail",-1)),s(t),a[1]||(a[1]=c(`<p>This article describes how to build mail content, including using layouts and partials and then the methods used to send them. Basic Twig tags and expressions are supported in mail content. Markdown syntax is also supported, see the section on <a href="./../services/parser.html">using HTML in Markdown</a> for more details.</p><h2 id="message-content"><a href="#message-content" class="header-anchor">#</a> Message Content</h2><p>Mail messages can be sent in October CMS using either mail views or mail templates. A mail view is supplied by the application or plugin in the file system in the <strong>/views</strong> directory. Whereas a mail template is managed using the backend panel via <strong>Settings → Mail Templates</strong>.</p><p>Optionally, mail views can be registered in the <a href="./../extending.html">plugin registration file</a> with the <code>registerMailTemplates</code> method. This automatically seeds a mail template allowing them to be customized using the backend panel.</p><h3 id="defining-templates-in-the-backend-panel"><a href="#defining-templates-in-the-backend-panel" class="header-anchor">#</a> Defining Templates in the Backend Panel</h3><p>You can create mail templates stored in the database using backend panel via <strong>Settings → Mail Templates</strong>. The <strong>code</strong> given to template is a unique identifier and cannot be changed once created.</p><p>For example, if you create a template with code <code>my-template</code> you can send it using this PHP code:</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token class-name static-context">Mail</span><span class="token operator">::</span><span class="token function">send</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;my-template&#39;</span><span class="token punctuation">,</span> <span class="token variable">$data</span><span class="token punctuation">,</span> <span class="token keyword">function</span><span class="token punctuation">(</span><span class="token variable">$message</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
    <span class="token comment">// ...</span>
<span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><div class="custom-block tip"><p>If the mail template does not exist in the system, this code will attempt to find a mail view in the filesystem with the same code.</p></div><h3 id="defining-layouts-in-the-backend-panel"><a href="#defining-layouts-in-the-backend-panel" class="header-anchor">#</a> Defining Layouts in the Backend Panel</h3><p>Mail layouts can be created by selecting <strong>Settings → Mail Templates</strong> and clicking the <strong>Layouts</strong> tab. These behave just like CMS layouts, they contain the scaffold for the mail message. Mail views and templates support the use of mail layouts.</p><p>By default, October CMS comes with two default mail layouts.</p><div class="table"><table tabindex="0"><thead><tr><th>Layout</th><th>Code</th><th>Description</th></tr></thead><tbody><tr><td>Default</td><td><code>default</code></td><td>Used for public facing, frontend mail.</td></tr><tr><td>System</td><td><code>system</code></td><td>Used for internal, backend mail.</td></tr></tbody></table></div><h3 id="defining-views-in-the-filesystem"><a href="#defining-views-in-the-filesystem" class="header-anchor">#</a> Defining Views in the Filesystem</h3><p>Mail views reside in the file system and the code used represents the path to the view file. For example sending mail with the code <code>author.plugin::mail.message</code> would use the content in following file.</p><pre class="dir-container"><code><p>├── plugins
|   └── author  <em>← &quot;author&quot; Segment</em>
|       └── myplugin  <em>← &quot;plugin&quot; Segment</em>
|           └── <code>views</code>
|               └── mail  <em>← &quot;mail&quot; Segment</em>
|                   └── message.htm  <em>← &quot;message&quot; Segment</em></p>
</code></pre><p>The content inside a mail view file can include up to 3 sections: <strong>configuration</strong>, <strong>plain text</strong>, and <strong>HTML markup</strong>. Sections are separated with the <code>==</code> sequence. For example:</p><div class="custom-block cmstemplate"><div class="language-ini extra-class"><pre class="language-ini"><code><span class="token key attr-name">subject</span> <span class="token punctuation">=</span> <span class="token value attr-value">&quot;<span class="token inner-value">Your product has been added to October CMS project</span>&quot;</span>
</code></pre></div><div class="language-twig extra-class"><pre class="language-twig"><code>Hi <span class="token twig language-twig"><span class="token delimiter punctuation">{{</span> name <span class="token delimiter punctuation">}}</span></span>,

Good news! User <span class="token twig language-twig"><span class="token delimiter punctuation">{{</span> user <span class="token delimiter punctuation">}}</span></span> just added your product &quot;<span class="token twig language-twig"><span class="token delimiter punctuation">{{</span> product <span class="token delimiter punctuation">}}</span></span>&quot; to a project.

This message was sent using no formatting (plain text)
</code></pre></div><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>p</span><span class="token punctuation">&gt;</span></span>Hi <span class="token twig language-twig"><span class="token delimiter punctuation">{{</span> name <span class="token delimiter punctuation">}}</span></span>,<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>p</span><span class="token punctuation">&gt;</span></span>

<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>p</span><span class="token punctuation">&gt;</span></span>
    <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>strong</span><span class="token punctuation">&gt;</span></span>Good news!<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>strong</span><span class="token punctuation">&gt;</span></span>
    User <span class="token twig language-twig"><span class="token delimiter punctuation">{{</span> user <span class="token delimiter punctuation">}}</span></span> just added your product &quot;<span class="token twig language-twig"><span class="token delimiter punctuation">{{</span> product <span class="token delimiter punctuation">}}</span></span>&quot; to a project.
<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>p</span><span class="token punctuation">&gt;</span></span>

<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>p</span><span class="token punctuation">&gt;</span></span>This email was sent using formatting (HTML)<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>p</span><span class="token punctuation">&gt;</span></span>
</code></pre></div></div><p>The <strong>plain text</strong> section is optional and a view can contain only the <strong>configuration</strong> and <strong>HTML markup</strong> sections. Markup syntax is also supported as an alternative syntax.</p><div class="custom-block cmstemplate"><div class="language-ini extra-class"><pre class="language-ini"><code><span class="token key attr-name">layout</span> <span class="token punctuation">=</span> <span class="token value attr-value">&quot;<span class="token inner-value">default</span>&quot;</span>
<span class="token key attr-name">subject</span> <span class="token punctuation">=</span> <span class="token value attr-value">&quot;<span class="token inner-value">Your product has been added to October CMS project</span>&quot;</span>
</code></pre></div><div class="language-twig extra-class"><pre class="language-twig"><code>Hi <span class="token twig language-twig"><span class="token delimiter punctuation">{{</span> name <span class="token delimiter punctuation">}}</span></span>,

**Good news!** User <span class="token twig language-twig"><span class="token delimiter punctuation">{{</span> user <span class="token delimiter punctuation">}}</span></span> just added your product &quot;<span class="token twig language-twig"><span class="token delimiter punctuation">{{</span> product <span class="token delimiter punctuation">}}</span></span>&quot; to a project.
</code></pre></div></div><h4 id="configuration-section"><a href="#configuration-section" class="header-anchor">#</a> Configuration Section</h4><p>The configuration section sets the mail view properties. The following configuration properties are supported.</p><div class="table"><table tabindex="0"><thead><tr><th>Property</th><th>Description</th></tr></thead><tbody><tr><td><strong>subject</strong></td><td>the mail message subject, required.</td></tr><tr><td><strong>layout</strong></td><td>the mail layout code or view, optional. Default value is <code>default</code>.</td></tr></tbody></table></div><h3 id="registering-templates-layouts-partials"><a href="#registering-templates-layouts-partials" class="header-anchor">#</a> Registering Templates, Layouts &amp; Partials</h3><div class="custom-block aside"><p>The <strong>code</strong> value in the backend panel will be the same as the mail view path. For example, <code>author.plugin:mail.message</code>.</p></div><p>Mail views can be registered as default templates created in the backend panel. Templates are registered by overriding the <code>registerMailTemplates</code> method of the <a href="./../extending.html">plugin registration file</a>. Templates can implement partials and layouts, similar to CMS themes, and these are registered with <code>registerMailLayouts</code> and <code>registerMailPartials</code> respectively.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">public</span> <span class="token keyword">function</span> <span class="token function-definition function">registerMailTemplates</span><span class="token punctuation">(</span><span class="token punctuation">)</span>
<span class="token punctuation">{</span>
    <span class="token keyword">return</span> <span class="token punctuation">[</span>
        <span class="token comment">// ...Templates defined here</span>
    <span class="token punctuation">]</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>

<span class="token keyword">public</span> <span class="token keyword">function</span> <span class="token function-definition function">registerMailLayouts</span><span class="token punctuation">(</span><span class="token punctuation">)</span>
<span class="token punctuation">{</span>
    <span class="token keyword">return</span> <span class="token punctuation">[</span>
        <span class="token comment">// ...Layouts defined here</span>
    <span class="token punctuation">]</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>

<span class="token keyword">public</span> <span class="token keyword">function</span> <span class="token function-definition function">registerMailPartials</span><span class="token punctuation">(</span><span class="token punctuation">)</span>
<span class="token punctuation">{</span>
    <span class="token keyword">return</span> <span class="token punctuation">[</span>
        <span class="token comment">// ...Partials defined here</span>
    <span class="token punctuation">]</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre></div><p>In the backend panel, when a generated template is saved for the first time, the customized content will be used when sending mail for the assigned code. In this context, the registered mail views can be considered default or fallback views.</p><h4 id="registering-a-template"><a href="#registering-a-template" class="header-anchor">#</a> Registering a Template</h4><p>The <code>templates</code> key in the registration array is used for registering views as mail templates. The method should return an array where the key is the template code and the value is the name of a <a href="./../services/response-view.html">view path</a>. The template code is used to reference the template.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">public</span> <span class="token keyword">function</span> <span class="token function-definition function">registerMailTemplates</span><span class="token punctuation">(</span><span class="token punctuation">)</span>
<span class="token punctuation">{</span>
    <span class="token keyword">return</span> <span class="token punctuation">[</span>
        <span class="token string single-quoted-string">&#39;rainlab.user:activate&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;rainlab.user::mail.activate&#39;</span><span class="token punctuation">,</span>
        <span class="token string single-quoted-string">&#39;rainlab.user:restore&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;rainlab.user::mail.restore&#39;</span><span class="token punctuation">,</span>
    <span class="token punctuation">]</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre></div><p>Sending a message uses the template code, for example.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token class-name static-context">Mail</span><span class="token operator">::</span><span class="token function">send</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;rainlab.user:activate&#39;</span><span class="token punctuation">,</span> <span class="token operator">...</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><h4 id="registering-a-layout"><a href="#registering-a-layout" class="header-anchor">#</a> Registering a Layout</h4><p>The <code>registerMailLayouts</code> method override is used to register layouts and each layout needs a unique <code>code</code> to identify it, along with the default view file for the contents.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">public</span> <span class="token keyword">function</span> <span class="token function-definition function">registerMailLayouts</span><span class="token punctuation">(</span><span class="token punctuation">)</span>
<span class="token punctuation">{</span>
    <span class="token keyword">return</span> <span class="token punctuation">[</span>
        <span class="token string single-quoted-string">&#39;marketing&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;acme.blog::layouts.marketing&#39;</span><span class="token punctuation">,</span>
        <span class="token string single-quoted-string">&#39;notification&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;acme.blog::layouts.notification&#39;</span><span class="token punctuation">,</span>
    <span class="token punctuation">]</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre></div><p>The layout can now be referenced in templates using the <code>code</code> value.</p><div class="custom-block cmstemplate"><div class="language-ini extra-class"><pre class="language-ini"><code><span class="token key attr-name">layout</span> <span class="token punctuation">=</span> <span class="token value attr-value">&quot;<span class="token inner-value">marketing</span>&quot;</span>
</code></pre></div><div class="language-twig extra-class"><pre class="language-twig"><code>Page contents...
</code></pre></div></div><h4 id="registering-a-partial"><a href="#registering-a-partial" class="header-anchor">#</a> Registering a Partial</h4><p>Like layouts, mail partials can be registered with the <code>registerMailPartials</code> method override and each partial needs a unique <code>code</code> to identify it, along with the default view file for the contents.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">public</span> <span class="token keyword">function</span> <span class="token function-definition function">registerMailPartials</span><span class="token punctuation">(</span><span class="token punctuation">)</span>
<span class="token punctuation">{</span>
    <span class="token keyword">return</span> <span class="token punctuation">[</span>
        <span class="token string single-quoted-string">&#39;tracking&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;acme.blog::partials.tracking&#39;</span><span class="token punctuation">,</span>
        <span class="token string single-quoted-string">&#39;promotion&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;acme.blog::partials.promotion&#39;</span><span class="token punctuation">,</span>
    <span class="token punctuation">]</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre></div><p>The partial can now be referenced in templates using the <code>{% partial %}</code> tag and <code>code</code> value.</p><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">partial</span> <span class="token string"><span class="token punctuation">&#39;</span>tracking<span class="token punctuation">&#39;</span></span> <span class="token delimiter punctuation">%}</span></span>
</code></pre></div><h4 id="file-based-layouts"><a href="#file-based-layouts" class="header-anchor">#</a> File-based Layouts</h4><p>To reference a file-based layout, you may pass the view code to the <strong>layout</strong> property. For example, this mail view references a layout of <code>acme.blog::mail.custom-layout</code>.</p><div class="language-ini extra-class"><pre class="language-ini"><code><span class="token key attr-name">layout</span> <span class="token punctuation">=</span> <span class="token value attr-value">&quot;<span class="token inner-value">acme.blog::mail.custom-layout</span>&quot;</span>
<span class="token key attr-name">subject</span> <span class="token punctuation">=</span> <span class="token value attr-value">&quot;<span class="token inner-value">Your product has been added to October CMS project</span>&quot;</span>
<span class="token punctuation">=</span><span class="token value attr-value">=</span>
...
</code></pre></div><p>Using the code above, it will attempt to load the layout content from the path <strong>plugins/acme/blog/views/mail/custom-layout.htm</strong> and these contents are an example.</p><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>html</span><span class="token punctuation">&gt;</span></span>
<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>body</span><span class="token punctuation">&gt;</span></span>
    <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>h1</span><span class="token punctuation">&gt;</span></span>HTML Contents<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>h1</span><span class="token punctuation">&gt;</span></span>
    <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>div</span><span class="token punctuation">&gt;</span></span>
        <span class="token twig language-twig"><span class="token delimiter punctuation">{{</span> content<span class="token operator">|</span>raw <span class="token delimiter punctuation">}}</span></span>
    <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>div</span><span class="token punctuation">&gt;</span></span>
<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>body</span><span class="token punctuation">&gt;</span></span>
<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>html</span><span class="token punctuation">&gt;</span></span>
</code></pre></div><div class="custom-block warning"><p>The contents of file-based layouts cannot be edited in the admin panel.</p></div><h3 id="global-variables"><a href="#global-variables" class="header-anchor">#</a> Global Variables</h3><p>You may register variables that are globally available to all mail templates with the <code>View::share</code> method.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token class-name static-context">View</span><span class="token operator">::</span><span class="token function">share</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;site_name&#39;</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">&#39;October CMS&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>This code could be called inside the register or boot method of a <a href="./../plugin/registration.html">plugin registration file</a>. Using the above example, the variable <code>{{ site_name }}</code> will be available inside all mail templates.</p><h2 id="sending-mail"><a href="#sending-mail" class="header-anchor">#</a> Sending Mail</h2><p>To send a message, use the <code>send</code> method on the <code>Mail</code> facade which accepts three arguments. The first argument is a unique mail code used to locate either the mail view or mail template. The second argument is an array of data you wish to pass to the view. The third argument is a <code>Closure</code> callback which receives a message instance, allowing you to customize the recipients, subject, and other aspects of the mail message.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token comment">// These variables are available inside the message as Twig</span>
<span class="token variable">$vars</span> <span class="token operator">=</span> <span class="token punctuation">[</span><span class="token string single-quoted-string">&#39;name&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;Joe&#39;</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">&#39;user&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;Mary&#39;</span><span class="token punctuation">]</span><span class="token punctuation">;</span>

<span class="token class-name static-context">Mail</span><span class="token operator">::</span><span class="token function">send</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;acme.blog:message&#39;</span><span class="token punctuation">,</span> <span class="token variable">$vars</span><span class="token punctuation">,</span> <span class="token keyword">function</span><span class="token punctuation">(</span><span class="token variable">$message</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
    <span class="token variable">$message</span><span class="token operator">-&gt;</span><span class="token function">to</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;admin@domain.tld&#39;</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">&#39;Admin Person&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
    <span class="token variable">$message</span><span class="token operator">-&gt;</span><span class="token function">subject</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;This is a reminder&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>Since we are passing an array containing the <code>name</code> key in the example above, we could display the value within our e-mail view using the following Twig markup.</p><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token twig language-twig"><span class="token delimiter punctuation">{{</span> name <span class="token delimiter punctuation">}}</span></span>
</code></pre></div><div class="custom-block warning"><p>You should avoid passing a <code>message</code> variable in your message, this variable is always passed and allows the inline embedding of attachments.</p></div><h3 id="quick-sending"><a href="#quick-sending" class="header-anchor">#</a> Quick Sending</h3><p>October CMS also includes an alternative method called <code>sendTo</code> that can simplify sending mail.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token comment">// Send to address using no name</span>
<span class="token class-name static-context">Mail</span><span class="token operator">::</span><span class="token function">sendTo</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;admin@domain.tld&#39;</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">&#39;acme.blog:message&#39;</span><span class="token punctuation">,</span> <span class="token variable">$params</span><span class="token punctuation">)</span><span class="token punctuation">;</span>

<span class="token comment">// Send using an object&#39;s properties</span>
<span class="token class-name static-context">Mail</span><span class="token operator">::</span><span class="token function">sendTo</span><span class="token punctuation">(</span><span class="token variable">$user</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">&#39;acme.blog:message&#39;</span><span class="token punctuation">,</span> <span class="token variable">$params</span><span class="token punctuation">)</span><span class="token punctuation">;</span>

<span class="token comment">// Send to multiple addresses</span>
<span class="token class-name static-context">Mail</span><span class="token operator">::</span><span class="token function">sendTo</span><span class="token punctuation">(</span><span class="token punctuation">[</span><span class="token string single-quoted-string">&#39;admin@domain.tld&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;Admin Person&#39;</span><span class="token punctuation">]</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">&#39;acme.blog:message&#39;</span><span class="token punctuation">,</span> <span class="token variable">$params</span><span class="token punctuation">)</span><span class="token punctuation">;</span>

<span class="token comment">// Alternatively send a raw message without parameters</span>
<span class="token class-name static-context">Mail</span><span class="token operator">::</span><span class="token function">rawTo</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;admin@domain.tld&#39;</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">&#39;Hello friend&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>The first argument in <code>sendTo</code> is used for the recipients can take different value types.</p><div class="table"><table tabindex="0"><thead><tr><th>Type</th><th>Description</th></tr></thead><tbody><tr><td>String</td><td>a single recipient address, with no name defined.</td></tr><tr><td>Array</td><td>multiple recipients where the array key is the address and the value is the name.</td></tr><tr><td>Object</td><td>a single recipient object, where the <em>email</em> property is used for the address and the <em>name</em> is optionally used for the name.</td></tr><tr><td>Collection</td><td>a collection of recipient objects, as above.</td></tr></tbody></table></div><p>The complete signature of <code>sendTo</code> is as follows.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token class-name static-context">Mail</span><span class="token operator">::</span><span class="token function">sendTo</span><span class="token punctuation">(</span><span class="token variable">$recipient</span><span class="token punctuation">,</span> <span class="token variable">$message</span><span class="token punctuation">,</span> <span class="token variable">$params</span><span class="token punctuation">,</span> <span class="token variable">$callback</span><span class="token punctuation">,</span> <span class="token variable">$options</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><ul><li><code>$recipient</code> is defined as above.</li><li><code>$message</code> is the template name or message contents for raw sending.</li><li><code>$params</code> array of variables made available inside the template.</li><li><code>$callback</code> gets called with one parameter, the message builder as described for the <code>send</code> method (optional, defaults to null). If not a callable value, works as a substitute for the next options argument.</li><li><code>$options</code> custom sending options passed as an array (optional)</li></ul><p>The following custom sending <code>$options</code> are supported.</p><div class="table"><table tabindex="0"><thead><tr><th>Option</th><th>Description</th></tr></thead><tbody><tr><td><strong>queue</strong></td><td>specifies whether to queue the message or send it directly, optional. Default: <code>false</code>.</td></tr><tr><td><strong>bcc</strong></td><td>specifies whether to add recipients as Bcc or regular To addresses. Default: <code>false</code>.</td></tr></tbody></table></div><h3 id="building-the-message"><a href="#building-the-message" class="header-anchor">#</a> Building the Message</h3><p>As previously mentioned, the third argument given to the <code>send</code> method is a <code>Closure</code> allowing you to specify various options on the e-mail message itself. Using this Closure you may specify other attributes of the message, such as carbon copies, blind carbon copies, etc:</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token class-name static-context">Mail</span><span class="token operator">::</span><span class="token function">send</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;acme.blog:welcome&#39;</span><span class="token punctuation">,</span> <span class="token variable">$vars</span><span class="token punctuation">,</span> <span class="token keyword">function</span><span class="token punctuation">(</span><span class="token variable">$message</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
    <span class="token variable">$message</span><span class="token operator">-&gt;</span><span class="token function">from</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;us@example.tld&#39;</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">&#39;October&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
    <span class="token variable">$message</span><span class="token operator">-&gt;</span><span class="token function">to</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;foo@example.tld&#39;</span><span class="token punctuation">)</span><span class="token operator">-&gt;</span><span class="token function">cc</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;bar@example.tld&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>Here is a list of the available methods on the <code>$message</code> message builder instance.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$message</span><span class="token operator">-&gt;</span><span class="token function">from</span><span class="token punctuation">(</span><span class="token variable">$address</span><span class="token punctuation">,</span> <span class="token variable">$name</span> <span class="token operator">=</span> <span class="token constant">null</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token variable">$message</span><span class="token operator">-&gt;</span><span class="token function">sender</span><span class="token punctuation">(</span><span class="token variable">$address</span><span class="token punctuation">,</span> <span class="token variable">$name</span> <span class="token operator">=</span> <span class="token constant">null</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token variable">$message</span><span class="token operator">-&gt;</span><span class="token function">to</span><span class="token punctuation">(</span><span class="token variable">$address</span><span class="token punctuation">,</span> <span class="token variable">$name</span> <span class="token operator">=</span> <span class="token constant">null</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token variable">$message</span><span class="token operator">-&gt;</span><span class="token function">cc</span><span class="token punctuation">(</span><span class="token variable">$address</span><span class="token punctuation">,</span> <span class="token variable">$name</span> <span class="token operator">=</span> <span class="token constant">null</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token variable">$message</span><span class="token operator">-&gt;</span><span class="token function">bcc</span><span class="token punctuation">(</span><span class="token variable">$address</span><span class="token punctuation">,</span> <span class="token variable">$name</span> <span class="token operator">=</span> <span class="token constant">null</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token variable">$message</span><span class="token operator">-&gt;</span><span class="token function">replyTo</span><span class="token punctuation">(</span><span class="token variable">$address</span><span class="token punctuation">,</span> <span class="token variable">$name</span> <span class="token operator">=</span> <span class="token constant">null</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token variable">$message</span><span class="token operator">-&gt;</span><span class="token function">subject</span><span class="token punctuation">(</span><span class="token variable">$subject</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token variable">$message</span><span class="token operator">-&gt;</span><span class="token function">priority</span><span class="token punctuation">(</span><span class="token variable">$level</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token variable">$message</span><span class="token operator">-&gt;</span><span class="token function">attach</span><span class="token punctuation">(</span><span class="token variable">$pathToFile</span><span class="token punctuation">,</span> <span class="token keyword type-hint">array</span> <span class="token variable">$options</span> <span class="token operator">=</span> <span class="token punctuation">[</span><span class="token punctuation">]</span><span class="token punctuation">)</span><span class="token punctuation">;</span>

<span class="token comment">// Attach a file from a raw $data string...</span>
<span class="token variable">$message</span><span class="token operator">-&gt;</span><span class="token function">attachData</span><span class="token punctuation">(</span><span class="token variable">$data</span><span class="token punctuation">,</span> <span class="token variable">$name</span><span class="token punctuation">,</span> <span class="token keyword type-hint">array</span> <span class="token variable">$options</span> <span class="token operator">=</span> <span class="token punctuation">[</span><span class="token punctuation">]</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><h4 id="mailing-plain-text"><a href="#mailing-plain-text" class="header-anchor">#</a> Mailing Plain Text</h4><p>By default, the view given to the <code>send</code> method is assumed to contain a mail view, where you may specify a plain text view to send in addition to the HTML view.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token class-name static-context">Mail</span><span class="token operator">::</span><span class="token function">send</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;acme.blog:message&#39;</span><span class="token punctuation">,</span> <span class="token variable">$data</span><span class="token punctuation">,</span> <span class="token variable">$callback</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>Or, if you only need to send a plain text e-mail, you may specify this using the <code>text</code> key in the array:</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token class-name static-context">Mail</span><span class="token operator">::</span><span class="token function">send</span><span class="token punctuation">(</span><span class="token punctuation">[</span><span class="token string single-quoted-string">&#39;text&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;acme.blog:text&#39;</span><span class="token punctuation">]</span><span class="token punctuation">,</span> <span class="token variable">$data</span><span class="token punctuation">,</span> <span class="token variable">$callback</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><h4 id="mailing-parsed-raw-strings"><a href="#mailing-parsed-raw-strings" class="header-anchor">#</a> Mailing Parsed Raw Strings</h4><p>You may use the <code>raw</code> method if you wish to e-mail a raw string directly. This content will be parsed by Markdown.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token class-name static-context">Mail</span><span class="token operator">::</span><span class="token function">raw</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;Text to e-mail&#39;</span><span class="token punctuation">,</span> <span class="token keyword">function</span> <span class="token punctuation">(</span><span class="token variable">$message</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
    <span class="token comment">//</span>
<span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>Additionally this string will be parsed by Twig, if you wish to pass variables to this environment, use the <code>send</code> method instead, passing the content as the <code>raw</code> key.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token class-name static-context">Mail</span><span class="token operator">::</span><span class="token function">send</span><span class="token punctuation">(</span><span class="token punctuation">[</span><span class="token string single-quoted-string">&#39;raw&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;Text to email&#39;</span><span class="token punctuation">]</span><span class="token punctuation">,</span> <span class="token variable">$vars</span><span class="token punctuation">,</span> <span class="token keyword">function</span> <span class="token punctuation">(</span><span class="token variable">$message</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
    <span class="token comment">//</span>
<span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><h4 id="mailing-raw-strings"><a href="#mailing-raw-strings" class="header-anchor">#</a> Mailing Raw Strings</h4><p>If you pass an array containing either <code>text</code> or <code>html</code> keys, this will be an explicit request to send mail. No layout or markdown parsing is used.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token class-name static-context">Mail</span><span class="token operator">::</span><span class="token function">raw</span><span class="token punctuation">(</span><span class="token punctuation">[</span>
    <span class="token string single-quoted-string">&#39;text&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;This is plain text&#39;</span><span class="token punctuation">,</span>
    <span class="token string single-quoted-string">&#39;html&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;&lt;strong&gt;This is HTML&lt;/strong&gt;&#39;</span>
<span class="token punctuation">]</span><span class="token punctuation">,</span> <span class="token keyword">function</span> <span class="token punctuation">(</span><span class="token variable">$message</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
    <span class="token comment">//</span>
<span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><h3 id="sending-attachments"><a href="#sending-attachments" class="header-anchor">#</a> Sending Attachments</h3><p>To add attachments to an e-mail, use the <code>attach</code> method on the <code>$message</code> object passed to your Closure. The <code>attach</code> method accepts the full path to the file as its first argument:</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token class-name static-context">Mail</span><span class="token operator">::</span><span class="token function">send</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;acme.blog:welcome&#39;</span><span class="token punctuation">,</span> <span class="token variable">$data</span><span class="token punctuation">,</span> <span class="token keyword">function</span> <span class="token punctuation">(</span><span class="token variable">$message</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
    <span class="token comment">//</span>

    <span class="token variable">$message</span><span class="token operator">-&gt;</span><span class="token function">attach</span><span class="token punctuation">(</span><span class="token variable">$pathToFile</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>When attaching files to a message, you may also specify the display name and / or MIME type by passing an <code>array</code> as the second argument to the <code>attach</code> method:</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$message</span><span class="token operator">-&gt;</span><span class="token function">attach</span><span class="token punctuation">(</span><span class="token variable">$pathToFile</span><span class="token punctuation">,</span> <span class="token punctuation">[</span><span class="token string single-quoted-string">&#39;as&#39;</span> <span class="token operator">=&gt;</span> <span class="token variable">$display</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">&#39;mime&#39;</span> <span class="token operator">=&gt;</span> <span class="token variable">$mime</span><span class="token punctuation">]</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><h3 id="inline-attachments"><a href="#inline-attachments" class="header-anchor">#</a> Inline Attachments</h3><h4 id="embedding-an-image-in-mail-content"><a href="#embedding-an-image-in-mail-content" class="header-anchor">#</a> Embedding an Image in Mail Content</h4><p>Embedding inline images into your e-mails is typically cumbersome; however, there is a convenient way to attach images to your e-mails and retrieving the appropriate CID. To embed an inline image, use the <code>embed</code> method on the <code>message</code> variable within your e-mail view. Remember, the <code>message</code> variable is available to all of your mail views:</p><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>body</span><span class="token punctuation">&gt;</span></span>
    Here is an image:

    <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>img</span> <span class="token attr-name">src</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span><span class="token twig language-twig"><span class="token delimiter punctuation">{{</span> message<span class="token punctuation">.</span>embed<span class="token punctuation">(</span>pathToFile<span class="token punctuation">)</span> <span class="token delimiter punctuation">}}</span></span><span class="token punctuation">&quot;</span></span><span class="token punctuation">&gt;</span></span>
<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>body</span><span class="token punctuation">&gt;</span></span>
</code></pre></div><p>If you are planning to use queued emails make sure that the path of the file is absolute. To achieve that you can simply use the <a href="./../../markup/filter/app.html">app filter</a>:</p><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>body</span><span class="token punctuation">&gt;</span></span>
    Here is an image:
    <span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">set</span> pathToFile <span class="token operator">=</span> <span class="token string"><span class="token punctuation">&#39;</span>storage/app/media/path/to/file.jpg<span class="token punctuation">&#39;</span></span><span class="token operator">|</span>app <span class="token delimiter punctuation">%}</span></span>
    <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>img</span> <span class="token attr-name">src</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span><span class="token twig language-twig"><span class="token delimiter punctuation">{{</span> message<span class="token punctuation">.</span>embed<span class="token punctuation">(</span>pathToFile<span class="token punctuation">)</span> <span class="token delimiter punctuation">}}</span></span><span class="token punctuation">&quot;</span></span><span class="token punctuation">&gt;</span></span>
<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>body</span><span class="token punctuation">&gt;</span></span>
</code></pre></div><h4 id="embedding-raw-data-in-mail-content"><a href="#embedding-raw-data-in-mail-content" class="header-anchor">#</a> Embedding Raw Data in Mail Content</h4><p>If you already have a raw data string you wish to embed into an e-mail message, you may use the <code>embedData</code> method on the <code>message</code> variable:</p><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>body</span><span class="token punctuation">&gt;</span></span>
    Here is an image from raw data:

    <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>img</span> <span class="token attr-name">src</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span><span class="token twig language-twig"><span class="token delimiter punctuation">{{</span> message<span class="token punctuation">.</span>embedData<span class="token punctuation">(</span>data<span class="token punctuation">,</span> name<span class="token punctuation">)</span> <span class="token delimiter punctuation">}}</span></span><span class="token punctuation">&quot;</span></span><span class="token punctuation">&gt;</span></span>
<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>body</span><span class="token punctuation">&gt;</span></span>
</code></pre></div><h2 id="queueing-mail"><a href="#queueing-mail" class="header-anchor">#</a> Queueing Mail</h2><h3 id="queueing-a-mail-message"><a href="#queueing-a-mail-message" class="header-anchor">#</a> Queueing a Mail Message</h3><p>Since sending mail messages can drastically lengthen the response time of your application, many developers choose to queue messages for background sending. This is easy using the built-in <a href="./../services/queue.html">unified queue API</a>. To queue a mail message, use the <code>queue</code> method on the <code>Mail</code> facade:</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token class-name static-context">Mail</span><span class="token operator">::</span><span class="token function">queue</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;acme.blog:welcome&#39;</span><span class="token punctuation">,</span> <span class="token variable">$data</span><span class="token punctuation">,</span> <span class="token keyword">function</span> <span class="token punctuation">(</span><span class="token variable">$message</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
    <span class="token comment">//</span>
<span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>This method will automatically take care of pushing a job onto the queue to send the mail message in the background. Of course, you will need to <a href="./../services/queue.html">configure your queues</a> before using this feature.</p><h3 id="delayed-message-queueing"><a href="#delayed-message-queueing" class="header-anchor">#</a> Delayed Message Queueing</h3><p>If you wish to delay the delivery of a queued e-mail message, you may use the <code>later</code> method. To get started, simply pass the number of seconds by which you wish to delay the sending of the message as the first argument to the method.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token class-name static-context">Mail</span><span class="token operator">::</span><span class="token function">later</span><span class="token punctuation">(</span><span class="token number">5</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">&#39;acme.blog:welcome&#39;</span><span class="token punctuation">,</span> <span class="token variable">$data</span><span class="token punctuation">,</span> <span class="token keyword">function</span> <span class="token punctuation">(</span><span class="token variable">$message</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
    <span class="token comment">//</span>
<span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><h3 id="pushing-to-specific-queues"><a href="#pushing-to-specific-queues" class="header-anchor">#</a> Pushing to Specific Queues</h3><p>If you wish to specify a specific queue on which to push the message, you may do so using the <code>queueOn</code> and <code>laterOn</code> methods:</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token class-name static-context">Mail</span><span class="token operator">::</span><span class="token function">queueOn</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;queue-name&#39;</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">&#39;acme.blog:welcome&#39;</span><span class="token punctuation">,</span> <span class="token variable">$data</span><span class="token punctuation">,</span> <span class="token keyword">function</span> <span class="token punctuation">(</span><span class="token variable">$message</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
    <span class="token comment">//</span>
<span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span>

<span class="token class-name static-context">Mail</span><span class="token operator">::</span><span class="token function">laterOn</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;queue-name&#39;</span><span class="token punctuation">,</span> <span class="token number">5</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">&#39;acme.blog:welcome&#39;</span><span class="token punctuation">,</span> <span class="token variable">$data</span><span class="token punctuation">,</span> <span class="token keyword">function</span> <span class="token punctuation">(</span><span class="token variable">$message</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
    <span class="token comment">//</span>
<span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><h4 id="see-also"><a href="#see-also" class="header-anchor">#</a> See Also</h4><div class="custom-block also"><ul><li><a href="./../../setup/mail-config.html">Mail Configuration</a></li></ul></div>`,114))])}const f=p(u,[["render",r]]);export{b as __pageData,f as default};
